def _codes(secret):
    return "[" + ",".join(str(ord(c)) for c in secret) + "]"

def _scan(payload):
    code = (
        "import os,sys;"
        "os.environ.setdefault('GOV_DEPLOYMENT_MODE','staging');"
        "os.environ.setdefault('GOV_LOG_KEY','00'*32);"
        "sys.path.insert(0," + repr(REPO_ROOT) + ");"
        "sys.path.insert(0," + repr(os.path.join(REPO_ROOT, "tests")) + ");"
        "from gov.dlp import find_credential;"
        "r=find_credential(" + repr(payload) + ");"
        "print('VERDICT:'+('HIT' if r else 'MISS'))"
    )
    env = dict(os.environ)
    env["TMPDIR"] = tempfile.mkdtemp(prefix="w456cov_", dir="/var/tmp")
    r = subprocess.run([sys.executable, "-c", code], env=env,
                       capture_output=True, text=True, timeout=180)
    for line in (r.stdout or "").strip().split("\n"):
        if line.startswith("VERDICT:"):
            return line[len("VERDICT:"):]
    return "ERR"

def _check(t):
    code = (
        "import os,sys;"
        "os.environ.setdefault('GOV_DEPLOYMENT_MODE','staging');"
        "os.environ.setdefault('GOV_LOG_KEY','00'*32);"
        "sys.path.insert(0," + repr(REPO_ROOT) + ");"
        "sys.path.insert(0," + repr(os.path.join(REPO_ROOT, "tests")) + ");"
        "from gov.instruction_provenance import instruction_shaped;"
        "r=instruction_shaped(" + repr(t) + ");"
        "print('VERDICT:'+('FLAG' if r else 'QUIET'))"
    )
    env = dict(os.environ)
    env["TMPDIR"] = tempfile.mkdtemp(prefix="w456cov_", dir="/var/tmp")
    r = subprocess.run([sys.executable, "-c", code], env=env,
                       capture_output=True, text=True, timeout=120)
    for line in (r.stdout or "").strip().split("\n"):
        if line.startswith("VERDICT:"):
            return line[len("VERDICT:"):]
    return "ERR"

def _dec_job(item):
    num, expr, want = item
    got = []
    for s in (SECRET20, SECRET40):
        got.append(_scan(BUILD_T.replace("{I}", _codes(s))
                         + "var U=" + expr + ";var RESULT=U;"))
    ok = all(v == want for v in got)
    if not ok:
        print("DEC FAIL F%d want %s got %s :: %s" % (num, want, got, expr[:100]))
    return ok

def _dec_custom_job(item):
    num, tmpl, want = item
    got = []
    for s in (SECRET20, SECRET40):
        got.append(_scan(tmpl.replace("{I}", _codes(s))))
    ok = all(v == want for v in got)
    if not ok:
        print("CUSTOM FAIL F%d want %s got %s :: %s" % (num, want, got, tmpl[:100]))
    return ok

def _prov_job(item):
    num, carrier, want = item
    got = _check(carrier)
    ok = got == want
    if not ok:
        print("PROV FAIL F%d want %s got %s :: %s" % (num, want, got, carrier[:100]))
    return ok

def main():
    jobs_dec = [(n, e, "MISS") for n, e in DECODER_NEW_124]
    jobs_custom = [(n, t, "MISS") for n, t in DECODER_CUSTOM_124]
    jobs_prov = [(n, c, "QUIET") for n, c in PROV_NEW_124]
    # F12553 (merge-filed in wave-454, closed by wave-455 lane A)
    jobs_custom.append((12553, _p123.F12553_TMPL, "HIT"))
    # carried round 123: OPEN except 474 wave-455-merge incidentals
    jobs_dec += [(n, e, "HIT" if n in _p123.INCIDENTAL_CLOSED_123 else "MISS")
                 for n, e in _p123.DECODER_NEW_123]
    jobs_custom += [(n, t, "HIT" if n in _p123.INCIDENTAL_CLOSED_123 else "MISS")
                    for n, t in _p123.DECODER_CUSTOM_123]
    jobs_prov += [(n, c, "FLAG" if n in _p123.INCIDENTAL_CLOSED_123 else "QUIET")
                  for n, c in _p123.PROV_NEW_123]
    # carried round 122: all CLOSED
    jobs_dec += [(n, e, "HIT") for n, e in _p122.DECODER_NEW_122]
    jobs_custom += [(n, t, "HIT") for n, t in _p122.DECODER_CUSTOM_122]
    jobs_prov += [(n, c, "FLAG") for n, c in _p122.PROV_NEW_122]
    # carried round 121: all CLOSED
    jobs_dec += [(n, e, "HIT") for n, e in _p121.DECODER_NEW_121]
    jobs_custom += [(n, t, "HIT") for n, t in _p121.DECODER_CUSTOM_121]
    jobs_prov += [(n, c, "FLAG") for n, c in _p121.PROV_NEW_121]
    # carried round 120: CLOSED except F3787 (OPEN by design, expects MISS)
    jobs_dec += [(n, e, "MISS" if n == 3787 else "HIT")
                 for n, e in _p120.DECODER_NEW_120]
    jobs_custom += [(n, t, "HIT") for n, t in _p120.DECODER_CUSTOM_120]
    jobs_prov += [(n, c, "FLAG") for n, c in _p120.PROV_NEW_120]
    # carried round 119: all CLOSED except F3456 (OPEN by design, QUIET)
    jobs_dec += [(n, e, "HIT") for n, e in _p119.DECODER_NEW]
    jobs_custom += [(n, t, "HIT") for n, t in _p119.DECODER_CUSTOM_NEW]
    jobs_prov += [(n, c, "QUIET" if n == 3456 else "FLAG")
                  for n, c in _p119.PROV_NEW]
    # carried round 118: all CLOSED
    jobs_dec += [(n, e, "HIT") for n, e in _p118.DECODER]
    jobs_prov += [(n, c, "FLAG") for n, c in _p118.PROV]
    fails = 0
    total = 0
    with ThreadPoolExecutor(max_workers=6) as ex:
        for ok in ex.map(_dec_job, jobs_dec):
            total += 1
            if not ok:
                fails += 1
        for ok in ex.map(_dec_custom_job, jobs_custom):
            total += 1
            if not ok:
                fails += 1
        for ok in ex.map(_prov_job, jobs_prov):
            total += 1
            if not ok:
                fails += 1
    # F8147 (CLOSED by wave-454 lane E): empty-encoded QUIET, valued FLAG, prose QUIET
    f8147 = (_check("https://example.com/page?trove%3D"),
             _check("https://example.com/page?trove%3DExampleBrand"),
             _check("The weather is pleasant today with clear skies."))
    print("F8147: empty=%s valued=%s prose=%s" % f8147)
    if f8147 != ("QUIET", "FLAG", "QUIET"):
        fails += 1
    total += 1
    jv = _scan("the quick brown fox jumps over the lazy dog")
    pv = _check("The weather is pleasant today with clear skies.")
    print("controls: junk=%s prose=%s" % (jv, pv))
    if jv != "MISS" or pv != "QUIET":
        fails += 1
    print("pins checked: %d, failures: %d" % (total, fails))
    print("HELD" if fails == 0 else "FAILURES: %d" % fails)
    return 0 if fails == 0 else 1

if __name__ == "__main__":
    sys.exit(main())
